const AWS = require('aws-sdk');
const express = require('express');
const ddb = new AWS.DynamoDB();
const sns = new AWS.SNS();
const app = express();
app.post('/signup', (req, res) => { ddb.putItem({}, () => sns.publish({}, () => res.send('ok'))); });
app.listen(process.env.PORT || 3000);

