files.app.py:
import os
import sqlite3
from flask import Flask, g, request, send_from_directory
DB_PATH = os.environ.get('RECETTES_DB', 'recettes.db')
UPLOADS = os.environ.get('RECETTES_UPLOADS', 'uploads')
app = Flask(__name__)
def db():
    g.db = sqlite3.connect(DB_PATH)
    return g.db
@app.post('/recettes')
def add():
    f = request.files.get('photo')
    f.save(os.path.join(UPLOADS, 'x.png'))
@app.get('/photos/<nom>')
def photo(nom):
    return send_from_directory(UPLOADS, nom)

